create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', email text, avatar_url text, role text not null default 'journalist' check (role in ('super_admin','admin','editor_in_chief','editor','journalist')), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, sort_order integer not null default 0, created_at timestamptz not null default now());
create table public.tags (id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique);
create table public.articles (id uuid primary key default gen_random_uuid(), author_id uuid references public.profiles(id) on delete set null, editor_id uuid references public.profiles(id) on delete set null, category_id uuid references public.categories(id) on delete set null, title text not null, slug text not null unique, excerpt text, content jsonb not null default '{}'::jsonb, featured_image text, source_name text, source_url text, status text not null default 'draft' check (status in ('draft','in_review','revision','scheduled','published','archived')), is_featured boolean not null default false, published_at timestamptz, scheduled_at timestamptz, view_count bigint not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.article_tags (article_id uuid not null references public.articles(id) on delete cascade, tag_id uuid not null references public.tags(id) on delete cascade, primary key(article_id,tag_id));
create table public.media (id uuid primary key default gen_random_uuid(), uploaded_by uuid references public.profiles(id) on delete set null, file_path text not null, file_name text not null, mime_type text, size_bytes bigint, alt_text text, caption text, created_at timestamptz not null default now());
create table public.article_media (article_id uuid not null references public.articles(id) on delete cascade, media_id uuid not null references public.media(id) on delete cascade, sort_order integer not null default 0, primary key(article_id,media_id));
create table public.events (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, description text, location text, cover_image text, starts_at timestamptz, ends_at timestamptz, status text not null default 'draft' check (status in ('draft','published','cancelled')), created_by uuid references public.profiles(id) on delete set null, created_at timestamptz not null default now());
create table public.comments (id uuid primary key default gen_random_uuid(), article_id uuid not null references public.articles(id) on delete cascade, name text not null, email text, body text not null, status text not null default 'pending' check (status in ('pending','approved','rejected')), created_at timestamptz not null default now());
create table public.article_views (id bigint generated always as identity primary key, article_id uuid not null references public.articles(id) on delete cascade, viewed_at timestamptz not null default now(), visitor_hash text);
create table public.revisions (id uuid primary key default gen_random_uuid(), article_id uuid not null references public.articles(id) on delete cascade, editor_id uuid references public.profiles(id) on delete set null, title text not null, content jsonb not null, note text, created_at timestamptz not null default now());
create table public.pages (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, content jsonb not null default '{}'::jsonb, is_published boolean not null default false, updated_at timestamptz not null default now());
create table public.newsletter_subscribers (id uuid primary key default gen_random_uuid(), email text not null unique, is_active boolean not null default true, created_at timestamptz not null default now());
create table public.site_settings (key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.activity_logs (id bigint generated always as identity primary key, actor_id uuid references public.profiles(id) on delete set null, action text not null, entity_type text, entity_id text, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());

create function public.current_user_role() returns text language sql stable security definer set search_path = '' as $$ select role from public.profiles where id=(select auth.uid()) and is_active=true $$;
create function public.is_editorial_staff() returns boolean language sql stable security definer set search_path = '' as $$ select coalesce(public.current_user_role() in ('super_admin','admin','editor_in_chief','editor','journalist'),false) $$;
create function public.can_publish_articles() returns boolean language sql stable security definer set search_path = '' as $$ select coalesce(public.current_user_role() in ('super_admin','admin','editor_in_chief','editor'),false) $$;
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',''),new.email) on conflict(id) do nothing; return new; end; $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();

do $$ declare t text; begin foreach t in array array['profiles','categories','tags','articles','article_tags','media','article_media','events','comments','article_views','revisions','pages','newsletter_subscribers','site_settings','activity_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;

create policy "Published articles are public" on public.articles for select to anon,authenticated using ((status='published' and published_at<=now()) or public.is_editorial_staff());
create policy "Journalists create own articles" on public.articles for insert to authenticated with check(public.is_editorial_staff() and author_id=(select auth.uid()));
create policy "Authors and editors update articles" on public.articles for update to authenticated using(public.is_editorial_staff() and (author_id=(select auth.uid()) or public.can_publish_articles())) with check(public.is_editorial_staff());
create policy "Editors delete articles" on public.articles for delete to authenticated using(public.current_user_role() in ('super_admin','admin','editor_in_chief'));
create policy "Categories public read" on public.categories for select to anon,authenticated using(true);
create policy "Staff manage categories" on public.categories for all to authenticated using(public.can_publish_articles()) with check(public.can_publish_articles());
create policy "Tags public read" on public.tags for select to anon,authenticated using(true);
create policy "Staff manage tags" on public.tags for all to authenticated using(public.can_publish_articles()) with check(public.can_publish_articles());
create policy "Profiles visible to staff" on public.profiles for select to authenticated using(public.is_editorial_staff());
create policy "Users update own profile" on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy "Staff manage article tags" on public.article_tags for all to authenticated using(public.is_editorial_staff()) with check(public.is_editorial_staff());
create policy "Staff manage media" on public.media for all to authenticated using(public.is_editorial_staff()) with check(public.is_editorial_staff());
create policy "Staff manage article media" on public.article_media for all to authenticated using(public.is_editorial_staff()) with check(public.is_editorial_staff());
create policy "Published events public read" on public.events for select to anon,authenticated using(status='published' or public.is_editorial_staff());
create policy "Staff manage events" on public.events for all to authenticated using(public.can_publish_articles()) with check(public.can_publish_articles());
create policy "Approved comments public read" on public.comments for select to anon,authenticated using(status='approved' or public.is_editorial_staff());
create policy "Public submit comments" on public.comments for insert to anon,authenticated with check(status='pending');
create policy "Staff moderate comments" on public.comments for update to authenticated using(public.can_publish_articles()) with check(public.can_publish_articles());
create policy "Public record article views" on public.article_views for insert to anon,authenticated with check(true);
create policy "Staff read article views" on public.article_views for select to authenticated using(public.is_editorial_staff());
create policy "Staff manage revisions" on public.revisions for all to authenticated using(public.is_editorial_staff()) with check(public.is_editorial_staff());
create policy "Published pages public read" on public.pages for select to anon,authenticated using(is_published or public.is_editorial_staff());
create policy "Editors manage pages" on public.pages for all to authenticated using(public.can_publish_articles()) with check(public.can_publish_articles());
create policy "Public subscribe newsletter" on public.newsletter_subscribers for insert to anon,authenticated with check(is_active=true);
create policy "Staff read newsletter" on public.newsletter_subscribers for select to authenticated using(public.can_publish_articles());
create policy "Staff update newsletter" on public.newsletter_subscribers for update to authenticated using(public.can_publish_articles()) with check(public.can_publish_articles());
create policy "Staff delete newsletter" on public.newsletter_subscribers for delete to authenticated using(public.can_publish_articles());
create policy "Public read selected settings" on public.site_settings for select to anon,authenticated using(key in ('site_name','tagline','logo_url','social_links'));
create policy "Admins manage settings" on public.site_settings for all to authenticated using(public.current_user_role() in ('super_admin','admin')) with check(public.current_user_role() in ('super_admin','admin'));
create policy "Admins read activity logs" on public.activity_logs for select to authenticated using(public.current_user_role() in ('super_admin','admin','editor_in_chief'));
create policy "Staff insert activity logs" on public.activity_logs for insert to authenticated with check(actor_id=(select auth.uid()) and public.is_editorial_staff());

create index articles_status_published_idx on public.articles(status,published_at desc);
create index articles_category_idx on public.articles(category_id);
create index articles_author_idx on public.articles(author_id);
create index article_views_article_date_idx on public.article_views(article_id,viewed_at desc);
create index comments_article_status_idx on public.comments(article_id,status);

insert into public.categories(name,slug,sort_order) values ('Berita Kampus','berita-kampus',1),('Kegiatan','kegiatan',2),('Organisasi','organisasi',3),('Akademik','akademik',4),('Prestasi','prestasi',5),('Kemahasiswaan','kemahasiswaan',6),('Pengumuman','pengumuman',7),('Opini','opini',8);
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('komsi-media','komsi-media',true,10485760,array['image/jpeg','image/png','image/webp','image/gif']);
create policy "Public read KOMSI media" on storage.objects for select to anon,authenticated using(bucket_id='komsi-media');
create policy "Editorial staff upload KOMSI media" on storage.objects for insert to authenticated with check(bucket_id='komsi-media' and public.is_editorial_staff());
create policy "Editorial staff update KOMSI media" on storage.objects for update to authenticated using(bucket_id='komsi-media' and public.is_editorial_staff()) with check(bucket_id='komsi-media' and public.is_editorial_staff());
create policy "Admins delete KOMSI media" on storage.objects for delete to authenticated using(bucket_id='komsi-media' and public.current_user_role() in ('super_admin','admin'));
